'use strict'

// RFC 9110 `token`
const tokenRE = /^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/
const mediaTypeRE = /^([!#$%&'*+\-.^_`|~0-9A-Za-z]+)\/([!#$%&'*+\-.^_`|~0-9A-Za-z]+)$/

/**
 * Parses a `Content-Type` header value into its media type and parameters.
 */
class ContentType {
  #mediaType = ''
  #type = ''
  #subtype = ''
  #parameters = new Map()
  #valid = true

  constructor (headerValue) {
    if (headerValue === undefined || headerValue === null || headerValue === '' || headerValue === 'undefined') {
      return
    }
    this.#parse(String(headerValue))
  }

  #parse (header) {
    const semi = header.indexOf(';')
    const head = (semi === -1 ? header : header.slice(0, semi)).trim()
    const match = mediaTypeRE.exec(head)
    if (match === null) {
      this.#valid = false
      return
    }
    this.#type = match[1].toLowerCase()
    this.#subtype = match[2].toLowerCase()
    this.#mediaType = `${this.#type}/${this.#subtype}`

    if (semi === -1) return
    this.#parseParameters(header, semi + 1)
  }

  #parseParameters (header, pos) {
    const len = header.length
    while (pos < len) {
      // skip whitespace
      while (pos < len && (header[pos] === ' ' || header[pos] === '\t')) pos++
      if (pos >= len) return
      if (header[pos] === ';') {
        pos++
        continue
      }

      const eq = header.indexOf('=', pos)
      const nextSemi = header.indexOf(';', pos)
      if (eq === -1 || (nextSemi !== -1 && nextSemi < eq)) {
        // parameter without a value, skip it
        if (nextSemi === -1) return
        pos = nextSemi + 1
        continue
      }
      const name = header.slice(pos, eq).trim().toLowerCase()
      pos = eq + 1

      let value
      if (header[pos] === '"') {
        let i = pos + 1
        let out = ''
        let closed = false
        while (i < len) {
          const ch = header[i]
          if (ch === '\\' && i + 1 < len) {
            out += header[i + 1]
            i += 2
            continue
          }
          if (ch === '"') {
            closed = true
            break
          }
          out += ch
          i++
        }
        if (closed) {
          value = out
          pos = i + 1
        } else {
          value = 'invalid quoted string'
          pos = len
        }
      } else {
        const end = header.indexOf(';', pos)
        const stop = end === -1 ? len : end
        value = header.slice(pos, stop).trim()
        pos = stop
      }

      if (tokenRE.test(name) && !this.#parameters.has(name)) {
        this.#parameters.set(name, value)
      }
    }
  }

  get isEmpty () {
    return this.#mediaType === ''
  }

  get isValid () {
    return this.#valid
  }

  get mediaType () {
    return this.#mediaType
  }

  get type () {
    return this.#type
  }

  get subtype () {
    return this.#subtype
  }

  get parameters () {
    return this.#parameters
  }

  toString () {
    let out = this.#mediaType
    for (const [name, value] of this.#parameters) {
      out += `; ${name}="${value.replace(/(["\\])/g, '\\$1')}"`
    }
    return out
  }
}

module.exports = ContentType
