  fastify.inject({
    method: 'GET',
    url: '/v1//inner/route'
  }, (err, res) => {
    t.assert.ifError(err)
    t.assert.strictEqual(res.statusCode, 404)
    completion.stepIn()
  })
  completion.patience.then(testDone)
})
